import * as THREE from './three.module.js';
import {armTo} from './arm-pose.js';
// Small articulated club spectators, with different builds, faces, hair and resting poses.
export function gallerySpectator(index=0){const root=new THREE.Group(),body=new THREE.Group();root.add(body);const skins=['#c79c7f','#a57455','#d4b195','#b9896b'],clothes=['#e9e4d5','#6c8892','#d2bba0','#4e6561','#b4b2aa'],mat=c=>new THREE.MeshStandardMaterial({color:c,roughness:.94}),skin=mat(skins[index%4]),cloth=mat(clothes[index%5]),hair=mat(['#4f4033','#736553','#b8b2a2','#302e2b'][index%4]),dark=mat('#403a32');
 function oval(parent,r,m,position,scale=[1,1,1]){const o=new THREE.Mesh(new THREE.SphereGeometry(r,20,14),m);o.position.set(...position);o.scale.set(...scale);o.castShadow=true;parent.add(o);return o;}
 function limb(a,b,r,m){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),length=A.distanceTo(B);const o=new THREE.Mesh(new THREE.CapsuleGeometry(r,Math.max(.001,length-2*r),5,16),m);o.position.copy(A).add(B).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),B.sub(A).normalize());o.castShadow=true;body.add(o);return o;}
 const torso=new THREE.Mesh(new THREE.LatheGeometry([[.15,-.24],[.19,-.18],[.22,.16],[.17,.26],[.08,.29]].map(p=>new THREE.Vector2(...p)),24),cloth);torso.position.y=1.07;torso.scale.z=.77;body.add(torso);limb([0,1.31,0],[0,1.43,0],.064,skin);
 const headGroup=new THREE.Group();headGroup.position.set(0,1.56,0);headGroup.rotation.y=[-.16,.12,.28,-.24][index%4];body.add(headGroup);oval(headGroup,.133,skin,[0,0,0],[.90,1.12,.92]);oval(headGroup,.083,skin,[0,-.066,.035],[1,.72,.85]);const cap=new THREE.Mesh(new THREE.SphereGeometry(.138,24,16,0,Math.PI*2,0,Math.PI*(index%3===0?.48:.40)),hair);cap.position.y=.023;cap.scale.set(.92,1.05,.95);headGroup.add(cap);oval(headGroup,.025,skin,[0,-.015,.126],[.65,1,1.1]);headGroup.userData.spectatorHead=true;const eyes=[];for(const side of [-1,1]){oval(headGroup,.029,skin,[side*.12,-.018,0],[.52,1,.70]);eyes.push(oval(headGroup,.009,dark,[side*.049,.012,.117],[1,.55,.5]));}oval(headGroup,.026,dark,[0,-.065,.118],[1,.12,.2]);
 const arms=[];for(const side of [-1,1]){const shoulder=[side*.21,1.24,0],elbow=[side*(index%2?.28:.33),1.02,.10],wrist=[side*(index%2?.08:.22),index%2?1.05:.85,.25];const sleeve=limb(shoulder,shoulder.map((v,i)=>v+(elbow[i]-v)*.48),.078,cloth),upper=limb(shoulder,elbow,.053,skin),joint=oval(body,.052,skin,elbow),forearm=limb(elbow,wrist,.043,skin),palm=oval(body,.048,skin,wrist,[.8,1,.65]);arms.push({side,shoulder,wrist,sleeve,upper,joint,forearm,palm});}
 function fit(mesh,a,b){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=B.clone().sub(A),g=mesh.geometry.parameters;mesh.position.copy(A).add(B).multiplyScalar(.5);mesh.scale.y=d.length()/(g.length+2*g.radius);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());}
 const headYaw=[-.16,.12,.28,-.24][index%4],lean=(index%3-1)*.055;let applauseStart=-100;root.applaud=time=>{applauseStart=time+index%4*.1;};root.animateSpectator=time=>{const t=time+index*.79,age=time-applauseStart,clap=age>=0&&age<2.7?Math.min(1,age/.25,(2.7-age)/.4):0;
 headGroup.rotation.y=headYaw+Math.sin(t*.43)*.16;headGroup.rotation.x=Math.sin(t*.61)*.045;body.rotation.z=lean+Math.sin(t*.38)*.025;body.rotation.x=(index%2?.05:-.025)+Math.sin(t*.29)*.015;body.position.y=Math.sin(t*.71)*.005;
 const blinkCycle=t%(4.2+index%3*.6),blink=blinkCycle<.16?.12+.88*Math.abs((blinkCycle-.08)/.08):1;eyes.forEach(e=>e.scale.y=.55*blink);
 for(const arm of arms){const target=[arm.side*(.035+.09*(.5+.5*Math.sin(age*16))),1.18,.34],desired=arm.wrist.map((v,i)=>v+(target[i]-v)*clap);const p=armTo(arm.shoulder,desired,[arm.side*.5,-.35,.1]);fit(arm.upper,p.shoulder,p.elbow);fit(arm.forearm,p.elbow,p.wrist);fit(arm.sleeve,p.shoulder,p.shoulder.map((v,i)=>v+(p.elbow[i]-v)*.5));arm.joint.position.set(...p.elbow);arm.palm.position.set(...p.wrist);}
 };root.animateSpectator(0);root.scale.setScalar(.66+(index%3)*.025);root.userData.gallerySpectator=true;return root;}
